import { useMemo, useRef, useState } from 'react'
import { calculateIncomeForMonth, calculateIncomeForRange, calculateLiveBudget, calculateRecurringRemaining, currentDateKey, dateTime, focusOptions, hashPassword, localDateKey, money, monthName, passwordChecks, paymentMethods, summarizeMonth } from '../data/appData'
import { Brand } from './Brand'
import { Icon } from './Icon'
import { PasswordRule } from './PasswordRule'

function BudgetApp({ auth, data, save, flash, notice, signOut }) {
  const [view, setView] = useState('home')
  const [addOpen, setAddOpen] = useState(false)
  const [addIncomeOpen, setAddIncomeOpen] = useState(false)
  const [quickActionsOpen, setQuickActionsOpen] = useState(false)
  const [editingExpense, setEditingExpense] = useState(null)
  const [categoryId, setCategoryId] = useState(data.categories[0]?.id || '')
  const [type, setType] = useState('')
  const [amount, setAmount] = useState('')
  const [note, setNote] = useState('')
  const [paymentMethod, setPaymentMethod] = useState('Efectivo')
  const [editingId, setEditingId] = useState(data.categories[0]?.id || '')
  const [newType, setNewType] = useState('')
  const [newCategory, setNewCategory] = useState({ name: '', budget: '', flow: '' })
  const [profileDraft, setProfileDraft] = useState(data.profile)
  const navigate = nextView => { setView(nextView); window.scrollTo({ top: 0, behavior: 'instant' }) }
  const currentMonth = localDateKey(new Date()).slice(0, 7)
  const monthExpenses = data.expenses.filter(item => localDateKey(item.createdAt).slice(0, 7) === currentMonth)
  const spent = monthExpenses.reduce((sum, item) => sum + item.amount, 0)
  const balanceAfterExpenses = Number(data.profile.available ?? data.profile.income) - spent
  const remaining = Math.max(0, balanceAfterExpenses)
  const dayOfMonth = new Date().getDate()
  const daysInMonth = new Date(new Date().getFullYear(), new Date().getMonth() + 1, 0).getDate()
  const recurringRemaining = data.recurringPayments?.length ? calculateRecurringRemaining(data.recurringPayments, dayOfMonth, data.expenses) : Number(data.profile.fixed || 0)
  const safeToSpendToday = calculateLiveBudget({ available: data.profile.available ?? data.profile.income, spent, goal: data.profile.goal, recurringRemaining, daysRemaining: daysInMonth - dayOfMonth + 1 })
  const category = data.categories.find(item => item.id === categoryId)
  const editing = data.categories.find(item => item.id === editingId)
  const totals = useMemo(() => monthExpenses.reduce((map, item) => ({ ...map, [item.categoryId]: (map[item.categoryId] || 0) + item.amount }), {}), [monthExpenses])
  const topCategory = [...data.categories].sort((a, b) => (totals[b.id] || 0) - (totals[a.id] || 0))[0]

  const addExpense = event => {
    event.preventDefault()
    const numericAmount = Number(amount)
    if (!categoryId || !type || !numericAmount || numericAmount <= 0) return flash('Elige categoría, tipo y monto.')
    save({ ...data, expenses: [...data.expenses, { id: crypto.randomUUID(), categoryId, type, amount: numericAmount, note: note.trim(), paymentMethod, createdAt: new Date().toISOString() }] }, { type: 'expense', title: 'Registraste un gasto', detail: `${type} · ${money(numericAmount)} · ${paymentMethod}` })
    setAmount(''); setType(''); setNote(''); setPaymentMethod('Efectivo'); setAddOpen(false); setView('home'); flash('Gasto guardado con fecha y hora actual.')
  }
  const updateEditing = patch => save({ ...data, categories: data.categories.map(item => item.id === editingId ? { ...item, ...patch } : item) })
  const deleteEditing = target => {
    const selected = target || editing
    if (!selected || !confirm(`¿Eliminar “${selected.name}”? Sus gastos anteriores seguirán en el historial.`)) return
    const categories = data.categories.filter(item => item.id !== selected.id); const fallback = categories[0]?.id || ''
    save({ ...data, categories }, { type: 'category', title: 'Eliminaste una categoría', detail: selected.name }); setEditingId(fallback); setCategoryId(fallback); flash('Categoría eliminada.')
  }
  const nav = [['home', 'Inicio', 'home'], ['categories', 'Categorías', 'tag']]
  const firstName = (data.profile.name || auth.name || 'tu').split(' ')[0]
  const theme = data.profile.theme || 'light'
  const toggleTheme = () => { const nextTheme = theme === 'dark' ? 'light' : 'dark'; save({ ...data, profile: { ...data.profile, theme: nextTheme } }, { type: 'profile', title: 'Cambiaste el tema visual', detail: nextTheme === 'dark' ? 'Modo oscuro activado.' : 'Modo claro activado.' }); flash(nextTheme === 'dark' ? 'Modo oscuro activado.' : 'Modo claro activado.') }

  return <div className={`app-shell ${theme === 'dark' ? 'theme-dark' : ''}`}>
    <aside className="sidebar"><div className="sidebar-brand"><Brand /><span className="beta-badge">BETA</span></div><nav className="main-nav">{nav.map(([id, label, icon]) => <button key={id} onClick={() => navigate(id)} className={view === id ? 'active' : ''}><Icon name={icon} size={18} /><span>{label}</span>{id === 'add' && <kbd>N</kbd>}</button>)}</nav><div className="sidebar-bottom"><div className="sidebar-note"><span className="green-dot" /> {import.meta.env.DEV ? 'Datos guardados en db.json local.' : 'Datos guardados en esta sesión.'}</div><button className="sidebar-user" onClick={() => navigate('settings')}><span className="avatar">{firstName.charAt(0).toUpperCase()}</span><span><b>{firstName}</b><small>Cuenta personal</small></span><Icon name="arrow" size={15} /></button></div></aside>
    <main className="app-main"><header className="topbar"><div className="mobile-brand"><Brand /></div><div className="topbar-date">{new Intl.DateTimeFormat('es-PE', { weekday: 'long', day: 'numeric', month: 'long' }).format(new Date())}</div><div className="topbar-actions"><span className="local-status"><span className="green-dot" /> Sesión temporal</span><button className="icon-button" onClick={() => { setAddIncomeOpen(false); toggleTheme() }} aria-label={theme === 'dark' ? 'Activar modo claro' : 'Activar modo oscuro'} title={theme === 'dark' ? 'Modo claro' : 'Modo oscuro'}><Icon name={theme === 'dark' ? 'sun' : 'moon'} size={17} /></button><button className="mobile-profile-button" onClick={() => navigate('settings')} aria-label="Abrir perfil" title="Perfil"><Icon name="user" size={17} /></button><div className="quick-actions"><button className="topbar-add" onClick={() => setQuickActionsOpen(!quickActionsOpen)} aria-label="Acciones rápidas" aria-expanded={quickActionsOpen} title="Acciones rápidas"><Icon name="plus" size={18} /></button>{quickActionsOpen && <div className="quick-actions-menu"><button onClick={() => { navigate('home'); setAddOpen(true); setAddIncomeOpen(false); setQuickActionsOpen(false) }}><Icon name="plus" size={16} /><span><b>Nuevo gasto</b><small>Registrar una compra</small></span></button><button onClick={() => { setAddOpen(false); setAddIncomeOpen(true); setQuickActionsOpen(false) }}><Icon name="trend" size={16} /><span><b>Nuevo ingreso</b><small>Registrar un ingreso real</small></span></button><button onClick={() => { setAddOpen(false); navigate('categories'); setQuickActionsOpen(false) }}><Icon name="tag" size={16} /><span><b>Nueva categoría</b><small>Ampliar tu mapa</small></span></button><button onClick={() => { setAddOpen(false); navigate('recurring'); setQuickActionsOpen(false) }}><Icon name="list" size={16} /><span><b>Nuevo compromiso</b><small>Programar un pago</small></span></button></div>}</div></div></header>
      <div className="route-content" key={`${view}-${addOpen}-${addIncomeOpen}`}>{addOpen ? <AddView data={data} categoryId={categoryId} setCategoryId={setCategoryId} category={category} type={type} setType={setType} amount={amount} setAmount={setAmount} note={note} setNote={setNote} paymentMethod={paymentMethod} setPaymentMethod={setPaymentMethod} addExpense={addExpense} onClose={() => setAddOpen(false)} /> : addIncomeOpen ? <IncomeAddView data={data} save={save} flash={flash} onClose={() => setAddIncomeOpen(false)} /> : view === 'home' ? <HomeView firstName={firstName} data={data} monthExpenses={monthExpenses} spent={spent} remaining={remaining} overBudget={balanceAfterExpenses < 0} safeToSpendToday={safeToSpendToday} money={money} save={save} flash={flash} setView={navigate} /> : view === 'analysis' ? <AnalysisView data={data} money={money} setView={navigate} /> : view === 'movements' ? <MovementsView data={data} monthExpenses={monthExpenses} currentMonth={currentMonth} save={save} flash={flash} onEditExpense={setEditingExpense} setView={navigate} /> : view === 'calendar' ? <CalendarView data={data} money={money} onEditExpense={setEditingExpense} setView={navigate} /> : view === 'money' ? <MoneyView data={data} save={save} flash={flash} setView={navigate} /> : view === 'recurring' ? <RecurringView data={data} save={save} flash={flash} setView={navigate} /> : view === 'categories' ? <CategoriesView data={data} save={save} editing={editing} editingId={editingId} setEditingId={setEditingId} updateEditing={updateEditing} deleteEditing={deleteEditing} newType={newType} setNewType={setNewType} newCategory={newCategory} setNewCategory={setNewCategory} flash={flash} /> : <SettingsView data={data} profileDraft={profileDraft} setProfileDraft={setProfileDraft} save={save} flash={flash} signOut={signOut} />}</div>
    </main>{editingExpense && <ExpenseEditModal expense={editingExpense} data={data} save={save} flash={flash} onClose={() => setEditingExpense(null)} />}{notice && <div className="toast">{notice}</div>}
  </div>
}

function HomeView({ firstName, data, monthExpenses, spent, remaining, overBudget, safeToSpendToday, money, save, flash, setView }) {
  const budgetTotal = data.categories.reduce((sum, item) => sum + Number(item.budget || 0), 0)
  const percent = Math.min(100, budgetTotal ? Math.round((spent / budgetTotal) * 1000) / 10 : 0)
  const budgetExceeded = budgetTotal > 0 && spent > budgetTotal
  return <section className="page"><div className="page-heading home-heading"><div><span className="eyebrow">Resumen mensual</span><h1>Hola, {firstName} <span className="wave">✦</span></h1><p>Este es el pulso de tus finanzas en <b>{monthName}</b>.</p></div></div>
    <div className="metrics-grid"><Metric label="Gastado este mes" value={money(spent)} helper={`${monthExpenses.length} movimientos registrados`} icon="trend" tone="amber" /><Metric label="Disponible ahora" value={money(remaining)} helper={overBudget || budgetExceeded ? 'Revisa el ritmo de tus gastos.' : 'Vas por buen camino'} icon="wallet" tone={overBudget || budgetExceeded ? 'red' : 'green'} /></div><LiveBudgetCard amount={safeToSpendToday} money={money} recurring={data.recurringPayments?.length || 0} /><UpcomingPayments data={data} save={save} flash={flash} money={money} /><HomeModules setView={setView} />
    <div className="dashboard-grid"><article className="panel budget-panel"><div className="panel-heading"><div><span className="panel-label">Ritmo de gasto</span><h2>Tu presupuesto mensual</h2></div><span className="soft-badge">{percent}% usado</span></div><div className="budget-number"><strong>{money(spent)}</strong><span>de {money(budgetTotal)} planificados</span></div><div className="big-progress"><span style={{ width: `${percent}%` }} /></div><div className="budget-meta"><span><i className={`dot ${budgetExceeded ? 'dot-red' : 'dot-green'}`} /> {budgetExceeded ? 'Sobre el plan' : 'Dentro del plan'}</span><span className="panel-label">Calendario y plan disponibles en el menú</span></div></article></div>
  </section>
}

function HomeModules({ setView }) {
  return <div className="home-modules"><button onClick={() => setView('movements')}><span><Icon name="list" size={17} /></span><b>Movimientos</b><small>Revisa tus ingresos y gastos</small><Icon name="arrow" size={14} /></button><button onClick={() => setView('calendar')}><span><Icon name="tag" size={17} /></span><b>Calendario</b><small>Explora tus gastos por fecha</small><Icon name="arrow" size={14} /></button><button onClick={() => setView('analysis')}><span><Icon name="trend" size={17} /></span><b>Análisis</b><small>Entiende cómo va tu mes</small><Icon name="arrow" size={14} /></button><button onClick={() => setView('money')}><span><Icon name="wallet" size={17} /></span><b>Mi dinero</b><small>Metas, ingresos y pagos</small><Icon name="arrow" size={14} /></button></div>
}

function UpcomingPayments({ data, save, flash, money }) {
  const month = localDateKey(new Date()).slice(0, 7); const payments = [...(data.recurringPayments || [])].filter(item => item.active !== false && !data.expenses.some(expense => (expense.recurringId === item.id || (!expense.recurringId && expense.type === item.name)) && localDateKey(expense.createdAt).slice(0, 7) === month)).sort((a, b) => a.dueDay - b.dueDay).slice(0, 4)
  const markPaid = item => { if (data.expenses.some(expense => (expense.recurringId === item.id || (!expense.recurringId && expense.type === item.name)) && localDateKey(expense.createdAt).slice(0, 7) === month)) return flash('Este pago ya está marcado como realizado.'); const categoryId = 'fixed'; const expense = { id: crypto.randomUUID(), categoryId, type: item.name, amount: Number(item.amount), note: `Pago recurrente del día ${item.dueDay}.`, paymentMethod: item.paymentMethod || 'Transferencia', recurringId: item.id, createdAt: new Date().toISOString() }; save({ ...data, expenses: [...data.expenses, expense] }, { type: 'recurring', title: 'Marcaste un pago como realizado', detail: `${item.name} · ${money(item.amount)}` }); flash(`${item.name} marcado como pagado.`) }
  if (!payments.length) return null
  return <article className="payments-home"><div className="payments-home-heading"><div><span className="panel-label">Compromisos pendientes</span><h2>¿Qué falta pagar?</h2></div><span className="soft-badge">Este mes</span></div><div className="payment-alert-list">{payments.map(item => <div className="payment-alert" key={item.id}><span className="payment-alert-icon"><Icon name="wallet" size={15} /></span><span><b>{item.name}</b><small>{money(item.amount)} · Día {item.dueDay} · {item.paymentMethod || 'Transferencia'}</small></span><button className="payment-status" onClick={() => markPaid(item)}>Marcar pago</button></div>)}</div></article>
}

function LiveBudgetCard({ amount, money, recurring }) {
  return <article className="live-budget-card"><span className="live-budget-icon"><Icon name="wallet" size={18} /></span><span><small>Presupuesto vivo</small><b>Puedes gastar hoy: {money(amount)}</b><em>{recurring ? `${recurring} pagos recurrentes considerados.` : 'Ajustado según tus gastos y tu meta.'}</em></span><span className="live-budget-status">En tiempo real</span></article>
}

function HumanInsight({ data, spent, budgetTotal, monthExpenses, money }) {
  const goal = Number(data.profile.goal || 0); const saved = Number(data.profile.saved || 0); const message = goal > 0 && saved === 0 ? 'Este mes todavía no registraste ahorro. Eso también es una señal útil: primero entendamos tus gastos.' : spent > budgetTotal * .8 ? `Ya usaste ${Math.round((spent / budgetTotal) * 100)}% de tus categorías planificadas. Revisa antes de que el mes se cierre.` : monthExpenses.length > 0 ? 'Cada registro te ayuda a tomar una decisión más tranquila en el siguiente movimiento.' : 'Todavía no hay suficientes movimientos para encontrar un patrón.'
  return <article className="human-insight"><span className="insight-icon"><Icon name="trend" size={17} /></span><span><b>Una lectura honesta de tu mes</b><small>{message}</small></span></article>
}

function RecoveryCard({ data, totals, money, setView }) {
  const topCategory = [...data.categories].sort((a, b) => (totals[b.id] || 0) - (totals[a.id] || 0))[0]
  const recurring = (data.recurringPayments || []).filter(item => item.active !== false).sort((a, b) => b.amount - a.amount)[0]
  const recommendation = recurring ? `Revisa ${recurring.name} de ${money(recurring.amount)} y después controla ${topCategory?.name || 'tu categoría principal'}.` : `Empieza revisando ${topCategory?.name || 'tu categoría principal'} y pausa gastos no esenciales.`
  return <article className="recovery-card"><span className="recovery-icon"><Icon name="trend" size={18} /></span><span><small>Modo recuperación</small><b>Este mes necesitas ajustar el ritmo.</b><em>{recommendation}</em></span><button className="text-action" onClick={() => setView('money')}>Revisar plan <Icon name="arrow" size={13} /></button></article>
}

function AnalysisView({ data, money, setView }) {
  const today = new Date(); const todayKey = localDateKey(today); const [period, setPeriod] = useState('month'); const [customStart, setCustomStart] = useState(todayKey); const [customEnd, setCustomEnd] = useState(todayKey)
  const getRange = () => { const end = new Date(today); let start = new Date(today); if (period === 'today') start = new Date(today); if (period === 'week') start.setDate(today.getDate() - 6); if (period === 'fortnight') start.setDate(today.getDate() - 13); if (period === 'month') start = new Date(today.getFullYear(), today.getMonth(), 1); if (period === 'year') start = new Date(today.getFullYear(), 0, 1); if (period === 'custom') return [customStart, customEnd]; return [localDateKey(start), localDateKey(end)] }
  const [rangeStart, rangeEnd] = getRange(); const expenses = data.expenses.filter(item => { const key = localDateKey(item.createdAt); return key >= rangeStart && key <= rangeEnd }); const total = expenses.reduce((sum, item) => sum + item.amount, 0); const categories = expenses.reduce((map, item) => ({ ...map, [item.categoryId]: (map[item.categoryId] || 0) + item.amount }), {}); const topCategory = [...data.categories].sort((a, b) => (categories[b.id] || 0) - (categories[a.id] || 0))[0]; const topAmount = categories[topCategory?.id] || 0; const goal = Number(data.profile.goal || 0); const saved = Number(data.profile.saved || 0); const income = calculateIncomeForRange(data.incomeEntries, rangeStart, rangeEnd); const insight = !expenses.length ? 'Todavía no hay movimientos en este periodo. Puedes empezar con un registro pequeño.' : goal > 0 && saved === 0 ? 'No registraste ahorro todavía. El objetivo de este análisis es ayudarte a entender el ritmo, no juzgarlo.' : `Tu mayor concentración está en ${topCategory?.name || 'una categoría'} con ${money(topAmount)}.`
  return <section className="page"><div className="page-heading"><div><span className="eyebrow">Lectura financiera</span><h1>Análisis</h1><p>Entiende cómo se mueve tu dinero en el periodo que elijas.</p></div><button className="icon-nav-button" onClick={() => setView('home')} aria-label="Volver a Inicio" title="Volver a Inicio"><Icon name="arrowLeft" size={18} /></button></div><div className="period-tabs">{[['today', 'Día'], ['week', 'Semana'], ['fortnight', 'Quincena'], ['month', 'Mes'], ['year', 'Año'], ['custom', 'Personalizado']].map(([id, label]) => <button key={id} className={period === id ? 'active' : ''} onClick={() => setPeriod(id)}>{label}</button>)}</div>{period === 'custom' && <div className="custom-range"><label className="form-label">Desde<input className="field" type="date" value={customStart} onChange={event => setCustomStart(event.target.value)} /></label><label className="form-label">Hasta<input className="field" type="date" value={customEnd} onChange={event => setCustomEnd(event.target.value)} /></label></div>}<div className="analysis-metrics"><Metric label="Gastado" value={money(total)} helper={`${expenses.length} movimientos`} icon="trend" tone="amber" /><Metric label="Promedio por movimiento" value={money(expenses.length ? total / expenses.length : 0)} helper="En el periodo seleccionado" icon="wallet" /><Metric label="Ingreso real" value={money(income)} helper="Registrado en el mes" icon="arrow" tone="green" /></div><SpendingChart expenses={expenses} money={money} /><div className="analysis-grid"><article className="panel analysis-insight"><span className="panel-label">Lectura de VYRA</span><h2>{insight}</h2><p>El análisis cambia según tus registros y el periodo seleccionado.</p></article><article className="panel category-analysis"><div className="panel-heading"><div><span className="panel-label">Distribución</span><h2>¿Dónde se concentró el gasto?</h2></div><span className="soft-badge">{rangeStart} → {rangeEnd}</span></div><div className="analysis-bars">{data.categories.filter(category => categories[category.id]).sort((a, b) => (categories[b.id] || 0) - (categories[a.id] || 0)).slice(0, 5).map(category => { const amount = categories[category.id]; const width = total ? Math.round((amount / total) * 100) : 0; return <div className="analysis-bar" key={category.id}><div><span>{category.name}</span><b>{money(amount)}</b></div><div className="analysis-bar-track"><i style={{ width: `${width}%` }} /></div></div> })}</div>{!expenses.length && <div className="table-empty">Aún no hay datos para analizar.</div>}</article></div></section>
}

function SpendingChart({ expenses, money }) {
  const ordered = [...expenses].sort((a, b) => new Date(a.createdAt) - new Date(b.createdAt)); let cumulative = 0; const values = ordered.map(item => { cumulative += item.amount; return cumulative }); const max = Math.max(...values, 1); const points = values.map((value, index) => `${values.length === 1 ? 300 : (index / (values.length - 1)) * 560 + 20},${150 - (value / max) * 120}`).join(' ')
  return <article className="panel spending-chart"><div className="panel-heading"><div><span className="panel-label">Evolución acumulada</span><h2>Cómo creció tu gasto</h2></div><strong>{money(values[values.length - 1] || 0)}</strong></div><svg viewBox="0 0 600 180" role="img" aria-label="Gráfico de evolución acumulada del gasto"><path className="chart-grid-line" d="M20 30H580M20 90H580M20 150H580" /><polyline points={points} /></svg><div className="chart-legend"><span><i /> Cada punto representa un movimiento registrado</span><span>{ordered.length} movimientos</span></div></article>
}

function CalendarView({ data, money, onEditExpense, setView }) {
  return <section className="page"><div className="page-heading"><div><span className="eyebrow">Historial financiero</span><h1>Calendario</h1><p>Muévete por los meses y selecciona fechas directamente en el calendario.</p></div><button className="icon-nav-button" onClick={() => setView('home')} aria-label="Volver a Inicio" title="Volver a Inicio"><Icon name="arrowLeft" size={18} /></button></div><BankCalendarPanel data={data} money={money} onEditExpense={onEditExpense} /></section>
}

function BankCalendarPanel({ data, money, onEditExpense }) {
  const today = new Date(); const currentMonthKey = localDateKey(today).slice(0, 7); const [cursor, setCursor] = useState(new Date(today.getFullYear(), today.getMonth(), 1)); const [selectedDate, setSelectedDate] = useState(currentDateKey); const [rangeStart, setRangeStart] = useState(''); const [rangeEnd, setRangeEnd] = useState('')
  const year = cursor.getFullYear(); const month = cursor.getMonth(); const visibleMonthKey = `${year}-${String(month + 1).padStart(2, '0')}`; const daysInMonth = new Date(year, month + 1, 0).getDate(); const offset = (new Date(year, month, 1).getDay() + 6) % 7; const cells = [...Array(offset).fill(null), ...Array.from({ length: daysInMonth }, (_, index) => index + 1)]
  const expenses = data.expenses.filter(item => localDateKey(item.createdAt).slice(0, 7) === visibleMonthKey); const incomes = (data.incomeEntries || []).filter(item => String(item.receivedDate || item.createdAt || '').slice(0, 7) === visibleMonthKey); const commitments = (data.recurringPayments || []).filter(item => item.active !== false)
  const moveMonth = direction => { const next = new Date(year, month + direction, 1); setCursor(next); setSelectedDate(localDateKey(next)); setRangeStart(''); setRangeEnd('') }
  const selectDate = date => { setSelectedDate(date); if (!rangeStart || rangeEnd) { setRangeStart(date); setRangeEnd('') } else if (date < rangeStart) { setRangeStart(date); setRangeEnd(rangeStart) } else setRangeEnd(date) }
  const dateEvents = date => { const dayExpenses = expenses.filter(item => localDateKey(item.createdAt) === date); const dayIncome = incomes.filter(item => String(item.receivedDate || item.createdAt).slice(0, 10) === date); const dayCommitments = visibleMonthKey >= currentMonthKey ? commitments.filter(item => `${visibleMonthKey}-${String(Math.min(Number(item.dueDay || 1), daysInMonth)).padStart(2, '0')}` === date && !dayExpenses.some(expense => expense.recurringId === item.id || (!expense.recurringId && expense.type === item.name))) : []; return { dayExpenses, dayIncome, dayCommitments } }
  const selected = dateEvents(selectedDate); const start = rangeStart || `${visibleMonthKey}-01`; const end = rangeEnd || (rangeStart || `${visibleMonthKey}-${String(daysInMonth).padStart(2, '0')}`); const rangeExpenses = data.expenses.filter(item => { const date = localDateKey(item.createdAt); return date >= start && date <= end }); const rangeIncome = (data.incomeEntries || []).filter(item => { const date = String(item.receivedDate || item.createdAt).slice(0, 10); return date >= start && date <= end }); const rangeSpent = rangeExpenses.reduce((sum, item) => sum + Number(item.amount || 0), 0); const rangeIncomeTotal = rangeIncome.reduce((sum, item) => sum + Number(item.amount || 0), 0); const selectedLabel = new Intl.DateTimeFormat('es-PE', { weekday: 'long', day: 'numeric', month: 'long' }).format(new Date(`${selectedDate}T12:00:00`))
  return <><div className="calendar-range-hint"><Icon name="list" size={16} /><span>{rangeEnd ? `Rango: ${rangeStart} → ${rangeEnd}` : 'Selecciona una fecha inicial y otra final para consultar un rango.'}</span></div><div className="calendar-layout"><article className="panel calendar-panel"><div className="calendar-header"><div><span className="panel-label">Movimientos e ingresos</span><h2>{new Intl.DateTimeFormat('es-PE', { month: 'long', year: 'numeric' }).format(cursor)}</h2></div><div className="calendar-tools"><button className="calendar-nav" onClick={() => moveMonth(-1)} aria-label="Mes anterior" title="Mes anterior"><Icon name="arrowLeft" size={15} /></button><button className="calendar-nav" onClick={() => moveMonth(1)} aria-label="Mes siguiente" title="Mes siguiente"><Icon name="arrow" size={15} /></button></div></div><div className="calendar-caption">{expenses.length + incomes.length} movimientos · toca una fecha</div><div className="calendar-weekdays">{['Lun', 'Mar', 'Mié', 'Jue', 'Vie', 'Sáb', 'Dom'].map(day => <span key={day}>{day}</span>)}</div><div className="calendar-grid">{cells.map((day, index) => { if (!day) return <span className="calendar-empty" key={`empty-${index}`} />; const date = localDateKey(new Date(year, month, day)); const events = dateEvents(date); const inRange = Boolean(rangeStart) && date >= start && date <= end; return <button key={date} className={`${selectedDate === date ? 'selected' : ''} ${date === currentDateKey ? 'today' : ''} ${inRange ? 'in-range' : ''}`} onClick={() => selectDate(date)}><span>{day}</span>{events.dayExpenses.length + events.dayIncome.length + events.dayCommitments.length > 0 && <i title="Hay movimientos" />}</button> })}</div></article><article className="panel day-detail"><div className="day-detail-heading"><div><span className="panel-label">Detalle del día</span><h2>{selectedLabel}</h2></div><span className="day-total">{money(selected.dayIncome.reduce((sum, item) => sum + Number(item.amount || 0), 0) - selected.dayExpenses.reduce((sum, item) => sum + Number(item.amount || 0), 0))}</span></div>{selected.dayIncome.map(item => <div className="calendar-expense calendar-income" key={`income-${item.id}`}><span className="expense-icon"><Icon name="trend" size={16} /></span><span><b>{item.name}</b><small>Ingreso recibido · {item.paymentMethod || 'Transferencia'}</small></span><strong>+{money(item.amount)}</strong></div>)}{selected.dayExpenses.map(item => <button className="calendar-expense" key={`expense-${item.id}`} onClick={() => onEditExpense(item)}><span className="expense-icon"><Icon name="tag" size={16} /></span><span><b>{item.type}</b><small>{data.categories.find(category => category.id === item.categoryId)?.name || 'Categoría eliminada'} · {item.paymentMethod || 'Efectivo'}{item.note ? ` · ${item.note}` : ''}</small></span><strong>−{money(item.amount)}</strong></button>)}{selected.dayCommitments.map(item => <div className="calendar-expense calendar-commitment" key={`commitment-${item.id}`}><span className="expense-icon"><Icon name="wallet" size={16} /></span><span><b>{item.name}</b><small>Compromiso programado · Día {item.dueDay}</small></span><strong>{money(item.amount)}</strong></div>)}{!selected.dayIncome.length && !selected.dayExpenses.length && !selected.dayCommitments.length && <div className="day-empty"><span className="empty-icon"><Icon name="list" size={19} /></span><b>No hay movimientos este día</b><small>Selecciona otra fecha o registra un movimiento con el botón +.</small></div>}<div className="day-detail-footer"><span>{selected.dayIncome.length + selected.dayExpenses.length + selected.dayCommitments.length} eventos</span><span className="calendar-help">Los compromisos futuros aparecen aquí sin alterar tu saldo.</span></div></article></div><div className="range-summary panel"><div><span className="panel-label">Rango seleccionado</span><h2>{start} → {end}</h2></div><strong>{money(rangeIncomeTotal - rangeSpent)}</strong><span>{rangeIncome.length} ingresos · {rangeExpenses.length} gastos · {money(rangeIncomeTotal)} recibidos</span></div></>
}

function CalendarPanel({ data, monthExpenses, money, setView, onEditExpense }) {
  const today = new Date()
  const [cursor, setCursor] = useState(new Date(today.getFullYear(), today.getMonth(), 1))
  const [selectedDate, setSelectedDate] = useState(currentDateKey)
  const year = cursor.getFullYear(); const month = cursor.getMonth(); const daysInMonth = new Date(year, month + 1, 0).getDate(); const offset = (new Date(year, month, 1).getDay() + 6) % 7; const visibleMonthKey = `${year}-${String(month + 1).padStart(2, '0')}`
  const cells = [...Array(offset).fill(null), ...Array.from({ length: daysInMonth }, (_, index) => index + 1)]
  const visibleExpenses = data.expenses.filter(item => localDateKey(item.createdAt).slice(0, 7) === visibleMonthKey)
  const selectedExpenses = data.expenses.filter(item => localDateKey(item.createdAt) === selectedDate)
  const selectedLabel = new Intl.DateTimeFormat('es-PE', { weekday: 'long', day: 'numeric', month: 'long' }).format(new Date(`${selectedDate}T12:00:00`))
  const selectedTotal = selectedExpenses.reduce((sum, item) => sum + item.amount, 0)
  const moveMonth = offset => { const next = new Date(year, month + offset, 1); setCursor(next); setSelectedDate(localDateKey(next)) }
  return <div className="calendar-layout"><article className="panel calendar-panel"><div className="calendar-header"><div><span className="panel-label">Calendario de gastos</span><h2>{new Intl.DateTimeFormat('es-PE', { month: 'long', year: 'numeric' }).format(cursor)}</h2></div><div className="calendar-tools"><button className="calendar-nav" onClick={() => moveMonth(-1)} aria-label="Mes anterior" title="Mes anterior"><Icon name="arrowLeft" size={15} /></button><button className="calendar-nav" onClick={() => moveMonth(1)} aria-label="Mes siguiente" title="Mes siguiente"><Icon name="arrow" size={15} /></button></div></div><div className="calendar-caption">{visibleExpenses.length} movimientos · selecciona un día</div><div className="calendar-weekdays">{['Lun', 'Mar', 'Mié', 'Jue', 'Vie', 'Sáb', 'Dom'].map(day => <span key={day}>{day}</span>)}</div><div className="calendar-grid">{cells.map((day, index) => { if (!day) return <span className="calendar-empty" key={`empty-${index}`} />; const dateKey = localDateKey(new Date(year, month, day)); const dayExpenses = visibleExpenses.filter(item => localDateKey(item.createdAt) === dateKey); return <button key={dateKey} className={`${selectedDate === dateKey ? 'selected' : ''} ${dateKey === currentDateKey ? 'today' : ''}`} onClick={() => setSelectedDate(dateKey)}><span>{day}</span>{dayExpenses.length > 0 && <i title={`${dayExpenses.length} movimientos`} />}</button> })}</div></article><article className="panel day-detail"><div className="day-detail-heading"><div><span className="panel-label">Detalle del día</span><h2>{selectedLabel}</h2></div><span className="day-total">{money(selectedTotal)}</span></div>{selectedExpenses.length ? <div className="day-expenses">{selectedExpenses.map(item => <button className="calendar-expense" key={item.id} onClick={() => onEditExpense(item)}><span className="expense-icon"><Icon name="tag" size={16} /></span><span><b>Compraste {item.type.toLowerCase()}</b><small>{data.categories.find(category => category.id === item.categoryId)?.name || 'Categoría eliminada'} · {item.paymentMethod || 'Efectivo'}{item.note ? ` · ${item.note}` : ''}</small></span><strong>−{money(item.amount)}</strong></button>)}</div> : <div className="day-empty"><span className="empty-icon"><Icon name="list" size={19} /></span><b>No registraste gastos este día</b><small>Selecciona otro día o agrega un movimiento con el botón +.</small></div>}<div className="day-detail-footer"><span>{selectedExpenses.length} {selectedExpenses.length === 1 ? 'movimiento' : 'movimientos'}</span><span className="calendar-help">Usa los filtros superiores para ampliar el rango</span></div></article></div>
}

function ExpenseEditModal({ expense, data, save, flash, onClose }) {
  const [note, setNote] = useState(expense.note || '')
  const category = data.categories.find(item => item.id === expense.categoryId)
  const updateNote = () => { save({ ...data, expenses: data.expenses.map(item => item.id === expense.id ? { ...item, note: note.trim() } : item) }, { type: 'expense', title: 'Editaste una nota', detail: expense.type }); flash('Nota actualizada.'); onClose() }
  return <div className="modal-backdrop" onMouseDown={event => { if (event.target === event.currentTarget) onClose() }}><div className="edit-modal">  <button className="modal-close" onClick={onClose} aria-label="Cerrar"><Icon name="close" size={16} /></button><span className="eyebrow">Detalle del movimiento</span><h2>Compraste {expense.type.toLowerCase()}</h2><p className="edit-meta">{category?.name || 'Categoría eliminada'} · {expense.paymentMethod || 'Efectivo'} · {money(expense.amount)} · {dateTime(expense.createdAt)}</p><label className="form-label">Nota<textarea className="field note-field" value={note} onChange={event => setNote(event.target.value)} placeholder="Añade una nota sobre este movimiento..." /></label><p className="edit-lock">Solo puedes editar la nota. El monto, categoría y método forman parte del registro original.</p><div className="edit-actions"><button className="secondary-button" onClick={onClose}>Cancelar</button><button className="primary-button" onClick={updateNote}>Guardar nota <Icon name="check" size={15} /></button></div></div></div>
}

function Metric({ label, value, helper, icon, tone = '', onClick }) { return <article className={`metric-card ${tone} ${onClick ? 'is-clickable' : ''}`} onClick={onClick} onKeyDown={event => { if (onClick && (event.key === 'Enter' || event.key === ' ')) onClick() }} role={onClick ? 'button' : undefined} tabIndex={onClick ? 0 : undefined}><div className="metric-top"><span>{label}</span><span className="metric-icon"><Icon name={icon} size={17} /></span></div><strong>{value}</strong><small>{helper}</small></article> }
function MoneyView({ data, save, flash, setView }) {
  const currentMonth = localDateKey(new Date()).slice(0, 7)
  const currentSpent = data.expenses.filter(item => localDateKey(item.createdAt).slice(0, 7) === currentMonth).reduce((sum, item) => sum + Number(item.amount || 0), 0)
  const [draft, setDraft] = useState({ available: Math.max(0, Number(data.profile.available ?? data.profile.income ?? 0) - currentSpent), focus: data.profile.focus || 'Controlar mis gastos', goal: data.profile.goal || '', saved: data.profile.saved || 0 })
  const [panel, setPanel] = useState('overview')
  const savePlan = event => { event.preventDefault(); const profile = { ...data.profile, focus: draft.focus, goal: Number(draft.goal) || 0, saved: Number(draft.saved) || 0 }; save({ ...data, profile }, { type: 'money', title: 'Actualizaste tus metas', detail: `Enfoque: ${profile.focus}.` }); flash('Metas actualizadas.') }
  const goalProgress = Number(draft.goal) > 0 ? Math.min(100, Math.round((Number(draft.saved) / Number(draft.goal)) * 100)) : 0
  return <section className="page narrow-page"><div className="page-heading"><div><span className="eyebrow">Panorama financiero</span><h1>{panel === 'overview' ? 'Mi dinero' : panel === 'plan' ? 'Editar metas' : 'Módulos de mi dinero'}</h1><p>{panel === 'overview' ? 'Tu saldo real, tus metas y el historial de tus movimientos.' : 'Usa la flecha para volver al resumen de Mi dinero.'}</p></div>{panel !== 'overview' && <button className="icon-nav-button" onClick={() => setPanel('overview')} aria-label="Volver a Mi dinero" title="Volver a Mi dinero"><Icon name="arrowLeft" size={18} /></button>}</div>{panel === 'overview' && <div className="money-overview"><article className="panel money-highlight is-clickable" onClick={() => setPanel('plan')} role="button" tabIndex="0"><span className="panel-label">Disponible ahora</span><strong>{money(Number(draft.available) || 0)}</strong><p>Este monto se actualiza con tus ingresos y gastos reales.</p><div className="money-highlight-foot"><span><Icon name="wallet" size={15} /> Saldo actual</span>  <span className="soft-badge">En tiempo real</span></div></article><article className="panel money-goal is-clickable" onClick={() => setPanel('modules')} role="button" tabIndex="0"><div className="panel-heading"><div><span className="panel-label">Tu intención</span><h2>{draft.focus}</h2></div><div className="insight-icon"><Icon name="trend" size={18} /></div></div><p>{draft.goal ? <>Has registrado <b>{money(Number(draft.saved) || 0)}</b> de una meta de {money(Number(draft.goal))}.</> : 'Todavía no has definido cuánto quieres reservar cada mes.'}</p><div className="goal-line"><span style={{ width: `${goalProgress}%` }} /></div><small>{draft.goal ? (goalProgress ? `${goalProgress}% de tu meta registrada.` : 'Sin ahorro registrado todavía. Eso también es información real.') : 'Añade una meta para empezar a medirla.'}</small></article></div>}{panel === 'plan' && <form className="panel money-form" onSubmit={savePlan}><div className="panel-heading"><div><span className="panel-label">Metas del mes</span><h2>Ahorro y prioridades</h2></div><span className="soft-badge">Sesión temporal</span></div><label className="form-label">¿Qué quieres mejorar?<select className="field" value={draft.focus} onChange={event => setDraft({ ...draft, focus: event.target.value })}>{focusOptions.map(option => <option key={option.id} value={option.id}>{option.title}</option>)}</select></label><div className="form-grid"><label className="form-label">Meta de ahorro mensual <span className="optional">Opcional</span><div className="money-input"><span>S/</span><input type="number" min="0" step="0.01" value={draft.goal} onChange={event => setDraft({ ...draft, goal: event.target.value })} placeholder="0.00" /></div></label><label className="form-label">Ahorro real este mes<div className="money-input"><span>S/</span><input type="number" min="0" step="0.01" value={draft.saved} onChange={event => setDraft({ ...draft, saved: event.target.value })} placeholder="0.00" /></div></label></div><button className="primary-button" type="submit">Guardar metas <Icon name="arrow" size={16} /></button></form>}{panel === 'modules' ? <MoneyModules setView={setView} /> : panel === 'overview' ? <MonthCloseCard data={data} save={save} flash={flash} /> : null}</section>
}

function MoneyModules({ setView }) {
  return <div className="money-module-grid"><button className="panel money-module-card" onClick={() => setView('recurring')}><span className="insight-icon"><Icon name="list" size={18} /></span><span><b>Pagos recurrentes</b><small>Alquiler, internet, deudas y vencimientos.</small></span><Icon name="arrow" size={15} /></button></div>
}

function IncomeView({ data, save, flash }) {
  return <IncomeAddView data={data} save={save} flash={flash} onClose={() => window.history.back()} />

  const currentMonth = localDateKey(new Date()).slice(0, 7)
  const [mode, setMode] = useState('list')
  const [selectedMonth, setSelectedMonth] = useState(currentMonth)
  const [draft, setDraft] = useState({ name: '', amount: '', type: 'monthly', month: currentMonth, receivedDate: localDateKey(new Date()), paymentMethod: 'Efectivo', note: '' })
  const monthlyEntries = (data.incomeEntries || []).filter(item => item.type === 'monthly' && String(item.month || item.receivedDate || '').slice(0, 7) === selectedMonth)
  const oneTimeEntries = (data.incomeEntries || []).filter(item => item.type !== 'monthly' && String(item.receivedDate || '').slice(0, 7) === selectedMonth)
  const resetDraft = month => setDraft({ name: '', amount: '', type: 'monthly', month: month || selectedMonth, receivedDate: localDateKey(new Date()), paymentMethod: 'Efectivo', note: '' })
  const add = event => {
    event.preventDefault()
    const amount = Number(draft.amount)
    const targetMonth = draft.type === 'monthly' ? draft.month : draft.receivedDate.slice(0, 7)
    if (!draft.name.trim() || amount <= 0 || !targetMonth) return flash('Completa el nombre, el mes y el monto.')
    const entry = { id: crypto.randomUUID(), name: draft.name.trim(), amount, type: draft.type, month: targetMonth, receivedDate: draft.type === 'monthly' ? `${targetMonth}-01` : draft.receivedDate, paymentMethod: draft.paymentMethod, note: draft.note.trim() }
    const affectsAvailable = targetMonth === currentMonth
    save({ ...data, incomeEntries: [...(data.incomeEntries || []), entry], profile: { ...data.profile, available: Number(data.profile.available || 0) + (affectsAvailable ? amount : 0) } }, { type: 'income', title: draft.type === 'monthly' ? 'Registraste un ingreso mensual' : 'Registraste un ingreso puntual', detail: `${entry.name} · ${money(amount)} · ${targetMonth}` })
    setSelectedMonth(targetMonth); resetDraft(targetMonth); setMode('list'); flash('Ingreso real guardado en el mes elegido.')
  }
  const removeEntry = item => { const targetMonth = String(item.month || item.receivedDate || '').slice(0, 7); const affectsAvailable = targetMonth === currentMonth; save({ ...data, incomeEntries: (data.incomeEntries || []).filter(entry => entry.id !== item.id), profile: { ...data.profile, available: Number(data.profile.available || 0) - (affectsAvailable ? Number(item.amount || 0) : 0) } }, { type: 'income', title: 'Quitaste un ingreso', detail: item.name }); flash('Ingreso eliminado.') }
  return <section className="page narrow-page"><div className="page-heading"><div><span className="eyebrow">Mi dinero</span><h1>Ingresos reales</h1><p>{mode === 'list' ? 'Registra lo que realmente recibiste, mes a mes, igual que tus gastos.' : 'Elige el mes al que pertenece este ingreso.'}</p></div>{mode === 'list' ? <button className="primary-button icon-only" onClick={() => setMode('form')} aria-label="Agregar ingreso" title="Agregar ingreso"><Icon name="plus" size={19} /></button> : <button className="icon-nav-button" onClick={() => setMode('list')} aria-label="Volver a ingresos" title="Volver a ingresos"><Icon name="arrowLeft" size={18} /></button>}</div>{mode === 'list' ? <><div className="income-month-selector"><label className="form-label">Mes consultado<input className="field" type="month" value={selectedMonth} onChange={event => setSelectedMonth(event.target.value)} /></label></div>{data.incomeSources?.length > 0 && <p className="legacy-note">Tienes fuentes antiguas configuradas. Ya no se cuentan como ingresos reales; registra cada cobro en el mes correspondiente.</p>}<div className="income-sections"><article className="panel module-list"><div className="panel-heading"><div><span className="panel-label">Ingresos mensuales recibidos</span><h2>{monthlyEntries.length} registrados en {selectedMonth}</h2></div><span className="soft-badge">Ingreso real</span></div><div className="tools-list">{monthlyEntries.length ? monthlyEntries.map(item => <div className="tool-row" key={item.id}><span><b>{item.name}</b><small>{money(item.amount)} · {selectedMonth}</small></span><button onClick={() => removeEntry(item)} className="icon-delete" aria-label={`Eliminar ${item.name}`}><Icon name="close" size={14} /></button></div>) : <div className="table-empty">No tienes ingresos mensuales registrados para este mes.</div>}</div></article><article className="panel module-list"><div className="panel-heading"><div><span className="panel-label">Ingresos puntuales</span><h2>{oneTimeEntries.length} registrados en {selectedMonth}</h2></div><span className="soft-badge">No recurrentes</span></div><div className="tools-list">{oneTimeEntries.length ? oneTimeEntries.map(item => <div className="tool-row" key={item.id}><span><b>{item.name}</b><small>{money(item.amount)} · {item.receivedDate} · {item.paymentMethod}</small></span><button onClick={() => removeEntry(item)} className="icon-delete" aria-label={`Eliminar ${item.name}`}><Icon name="close" size={14} /></button></div>) : <div className="table-empty">No tienes ingresos puntuales para este mes.</div>}</div></article></div></> : <form className="panel module-form" onSubmit={add}><div className="panel-heading"><div><span className="panel-label">Nuevo ingreso real</span><h2>Regístralo en su mes</h2></div></div><label className="form-label">Tipo<select className="field" value={draft.type} onChange={event => setDraft({ ...draft, type: event.target.value })}><option value="monthly">Ingreso mensual recibido</option><option value="one-time">Ingreso puntual</option></select></label><label className="form-label">Nombre<input className="field" value={draft.name} onChange={event => setDraft({ ...draft, name: event.target.value })} placeholder={draft.type === 'monthly' ? 'Sueldo de noviembre...' : 'CTS, devolución, préstamo devuelto...'} /></label><label className="form-label">Monto<input className="field" type="number" min="0" step="0.01" value={draft.amount} onChange={event => setDraft({ ...draft, amount: event.target.value })} placeholder="0.00" /></label>{draft.type === 'monthly' ? <label className="form-label">Mes del ingreso<input className="field" type="month" value={draft.month} onChange={event => setDraft({ ...draft, month: event.target.value })} /></label> : <><label className="form-label">Fecha recibida<input className="field" type="date" value={draft.receivedDate} onChange={event => setDraft({ ...draft, receivedDate: event.target.value })} /></label><label className="form-label">Medio de recepción<select className="field" value={draft.paymentMethod} onChange={event => setDraft({ ...draft, paymentMethod: event.target.value })}>{paymentMethods.map(method => <option key={method} value={method}>{method}</option>)}</select></label><label className="form-label">Nota<textarea className="field" value={draft.note} onChange={event => setDraft({ ...draft, note: event.target.value })} placeholder="Ej. CTS de noviembre" /></label></>}<div className="module-form-actions"><button type="button" className="icon-nav-button" onClick={() => setMode('list')} aria-label="Cancelar" title="Cancelar"><Icon name="arrowLeft" size={18} /></button><button className="primary-button" type="submit">Guardar ingreso <Icon name="check" size={16} /></button></div></form>}</section>
}

function RecurringView({ data, save, flash, setView }) {
  const [mode, setMode] = useState('list')
  const [draft, setDraft] = useState({ name: '', amount: '', dueDay: '', dueTime: '09:00', paymentMethod: 'Transferencia' })
  const add = event => { event.preventDefault(); if (!draft.name.trim() || Number(draft.amount) <= 0) return flash('Completa el pago y el monto.'); const item = { id: crypto.randomUUID(), name: draft.name.trim(), amount: Number(draft.amount), dueDay: Number(draft.dueDay) || 1, dueTime: draft.dueTime || '09:00', paymentMethod: draft.paymentMethod, active: true }; save({ ...data, recurringPayments: [...(data.recurringPayments || []), item] }, { type: 'money', title: 'Agregaste un pago recurrente', detail: item.name }); setDraft({ name: '', amount: '', dueDay: '', dueTime: '09:00', paymentMethod: 'Transferencia' }); setMode('list'); flash('Pago recurrente agregado.') }
  const remove = item => save({ ...data, recurringPayments: (data.recurringPayments || []).filter(payment => payment.id !== item.id) }, { type: 'money', title: 'Quitaste un pago recurrente', detail: item.name })
  const dueLabel = dueDay => { const difference = Number(dueDay) - new Date().getDate(); return difference < 0 ? 'Vencido este mes' : difference === 0 ? 'Vence hoy' : `Vence en ${difference} dias` }
  return <section className="page narrow-page"><div className="page-heading"><div><span className="eyebrow">Mi dinero</span><h1>Compromisos</h1><p>{mode === 'list' ? 'Consulta tus pagos programados.' : 'Programa un nuevo pago recurrente.'}</p></div>{mode === 'list' ? <button className="primary-button icon-only" onClick={() => setMode('form')} aria-label="Agregar compromiso" title="Agregar compromiso"><Icon name="plus" size={19} /></button> : <button className="icon-nav-button" onClick={() => setMode('list')} aria-label="Volver a compromisos" title="Volver a compromisos"><Icon name="arrowLeft" size={18} /></button>}</div>{mode === 'list' ? <article className="panel module-list"><div className="panel-heading"><div><span className="panel-label">Pagos recurrentes</span><h2>{data.recurringPayments?.length || 0} compromisos configurados</h2></div><span className="soft-badge">Este mes</span></div><div className="tools-list">{data.recurringPayments?.length ? data.recurringPayments.map(item => <div className="tool-row" key={item.id}><span><b>{item.name}</b><small>{money(item.amount)} · Día {item.dueDay} · {item.dueTime || '09:00'} · {item.paymentMethod || 'Transferencia'} · {dueLabel(item.dueDay)}</small></span><button onClick={() => remove(item)} className="icon-delete" aria-label={`Eliminar ${item.name}`}><Icon name="close" size={14} /></button></div>) : <div className="table-empty">Todavía no tienes pagos recurrentes.</div>}</div></article> : <form className="panel module-form" onSubmit={add}><div className="panel-heading"><div><span className="panel-label">Nuevo compromiso</span><h2>Agregar pago recurrente</h2></div></div><label className="form-label">Nombre<input className="field" value={draft.name} onChange={event => setDraft({ ...draft, name: event.target.value })} placeholder="Alquiler, internet, deuda..." /></label><label className="form-label">Monto<input className="field" type="number" min="0" step="0.01" value={draft.amount} onChange={event => setDraft({ ...draft, amount: event.target.value })} placeholder="0.00" /></label><div className="form-grid"><label className="form-label">Día de pago<input className="field" type="number" min="1" max="31" value={draft.dueDay} onChange={event => setDraft({ ...draft, dueDay: event.target.value })} placeholder="1" /></label><label className="form-label">Hora habitual<input className="field" type="time" value={draft.dueTime} onChange={event => setDraft({ ...draft, dueTime: event.target.value })} /></label></div><label className="form-label">Medio de pago<select className="field" value={draft.paymentMethod} onChange={event => setDraft({ ...draft, paymentMethod: event.target.value })}>{paymentMethods.map(method => <option key={method} value={method}>{method}</option>)}</select></label><div className="module-form-actions"><button type="button" className="icon-nav-button" onClick={() => setMode('list')} aria-label="Cancelar" title="Cancelar"><Icon name="arrowLeft" size={18} /></button><button className="primary-button" type="submit">Guardar compromiso <Icon name="check" size={16} /></button></div></form>}</section>
}

function MonthCloseCard({ data, save, flash }) {
  const month = localDateKey(new Date()).slice(0, 7); const expenses = data.expenses.filter(item => localDateKey(item.createdAt).slice(0, 7) === month); const spent = expenses.reduce((sum, item) => sum + item.amount, 0); const income = calculateIncomeForMonth(data.incomeEntries, month); const summary = summarizeMonth({ income, spent }); const closure = (data.monthlyClosures || []).find(item => item.month === month); const closeMonth = () => { if (closure) return flash('Este mes ya tiene un cierre.'); const item = { month, ...summary, saved: Math.max(0, income - spent), closedAt: new Date().toISOString() }; save({ ...data, monthlyClosures: [...(data.monthlyClosures || []), item] }, { type: 'money', title: 'Cerraste el mes', detail: `${month} · ${money(item.saved)} disponibles.` }); flash('Cierre mensual guardado.') }; const reopenMonth = () => { if (!closure || !confirm('¿Reabrir el cierre de este mes?')) return; save({ ...data, monthlyClosures: data.monthlyClosures.filter(item => item.month !== month) }, { type: 'money', title: 'Reabriste el mes', detail: month }); flash('Cierre mensual reabierto.') }
  return <><article className="panel close-panel"><div><span className="panel-label">Cierre mensual</span><h2>{closure ? 'Mes cerrado' : 'Tu resumen está listo'}</h2><p>{closure ? 'Este resumen queda guardado en tu historial.' : 'Guarda una fotografía de lo que ingresó, gastaste y quedó disponible.'}</p></div><div className="close-summary"><span><small>Ingresó</small><b>{money(income)}</b></span><span><small>Gastaste</small><b>{money(spent)}</b></span><span><small>Quedó</small><b>{money(closure?.saved ?? Math.max(0, income - spent))}</b></span></div><button className="secondary-button" onClick={closure ? reopenMonth : closeMonth}>{closure ? 'Reabrir mes' : 'Cerrar mes'} <Icon name={closure ? 'arrowLeft' : 'check'} size={14} /></button></article><MonthlyHistory data={data} money={money} /></>
}

function MonthlyHistory({ data, money }) {
  const currentMonth = localDateKey(new Date()).slice(0, 7)
  const months = Array.from({ length: 4 }, (_, index) => { const date = new Date(); date.setDate(1); date.setMonth(date.getMonth() - index); return `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, '0')}` })
  const getSummary = month => {
    const closure = (data.monthlyClosures || []).find(item => item.month === month)
    const income = calculateIncomeForMonth(data.incomeEntries, month)
    const spent = data.expenses.filter(item => localDateKey(item.createdAt).slice(0, 7) === month).reduce((sum, item) => sum + Number(item.amount || 0), 0)
    const saved = closure?.saved ?? Math.max(0, income - spent)
    return { income: closure?.income ?? income, spent: closure?.spent ?? spent, saved }
  }
  return <article className="panel monthly-history"><div className="panel-heading"><div><span className="panel-label">Seguimiento</span><h2>Cómo avanzó tu ahorro</h2></div><span className="soft-badge">Últimos 4 meses</span></div><div className="monthly-history-list">{months.map(month => { const summary = getSummary(month); const label = new Intl.DateTimeFormat('es-PE', { month: 'long', year: 'numeric' }).format(new Date(`${month}-01T12:00:00`)); return <div className={`monthly-history-row ${month === currentMonth ? 'current' : ''}`} key={month}><span><b>{label}</b><small>{month === currentMonth ? 'Mes en curso' : 'Cierre registrado'}</small></span><span><small>Ingresó</small><b>{money(summary.income)}</b></span><span><small>Gastó</small><b>{money(summary.spent)}</b></span><span className={summary.saved > 0 ? 'history-positive' : 'history-negative'}><small>Ahorro</small><b>{money(summary.saved)}</b></span></div> })}</div></article>
}

function ActivityItem({ item }) { const icon = item.type === 'expense' ? 'plus' : item.type === 'income' ? 'trend' : item.type === 'security' ? 'lock' : item.type === 'account' ? 'user' : item.type === 'money' || item.type === 'onboarding' ? 'wallet' : item.type === 'category' ? 'tag' : 'arrow'; return <div className="timeline-item"><span className="timeline-icon"><Icon name={icon} size={15} /></span><span className="timeline-copy"><b>{item.title}</b><small>{item.detail}</small></span><time>{dateTime(item.createdAt)}</time></div> }

function AddView({ data, categoryId, setCategoryId, category, type, setType, amount, setAmount, note, setNote, paymentMethod, setPaymentMethod, addExpense, onClose }) {
  return <section className="page add-page"><div className="page-heading"><div><span className="eyebrow">Nuevo movimiento</span><h1>Nuevo gasto</h1><p>Completa el registro sin abandonar Inicio.</p></div>{onClose && <button className="icon-nav-button" onClick={onClose} aria-label="Volver a Inicio" title="Volver a Inicio"><Icon name="arrowLeft" size={18} /></button>}</div><div className="add-layout"><div className="panel add-selection"><div className="step-block"><Step n="01" title="Elige una categoría" /><div className="category-picker">{data.categories.map(item => <button type="button" key={item.id} onClick={() => { setCategoryId(item.id); setType('') }} className={categoryId === item.id ? 'selected' : ''}><span>{item.name.charAt(0)}</span><b>{item.name}</b><small>{money(item.budget)}</small></button>)}</div></div>{category && <div className="step-block detail-block"><Step n="02" title="¿Qué fue?" /><div className="flow-tip"><b>{category.name}</b><span>{category.flow}</span></div><div className="type-pills">{category.types.map(item => <button type="button" key={item} onClick={() => setType(item)} className={type === item ? 'selected' : ''}>{item}</button>)}</div><label className="form-label">O escribe otro detalle<input className="field" value={type} onChange={event => setType(event.target.value)} placeholder="Ej. Pallar, canela, taxi al mall" /></label></div>}</div><form className="panel add-summary" onSubmit={addExpense}><Step n="03" title="Completa el gasto" /><label className="form-label">Monto (S/)<input className="field" value={amount} onChange={event => setAmount(event.target.value)} type="number" min="0.01" step="0.01" inputMode="decimal" placeholder="0.00" /></label><label className="form-label">Medio de pago<select className="field" value={paymentMethod} onChange={event => setPaymentMethod(event.target.value)}>{paymentMethods.map(method => <option key={method} value={method}>{method}</option>)}</select></label><label className="form-label">Nota opcional<textarea className="field note-field" value={note} onChange={event => setNote(event.target.value)} placeholder="Añade un contexto breve..." /></label><button className="primary-button full-button" type="submit">Guardar gasto <Icon name="arrow" size={17} /></button></form></div></section>
}

function IncomeAddView({ data, save, flash, onClose }) {
  const [name, setName] = useState('')
  const [amount, setAmount] = useState('')
  const [paymentMethod, setPaymentMethod] = useState('Efectivo')
  const [note, setNote] = useState('')
  const addIncome = event => {
    event.preventDefault()
    const numericAmount = Number(amount)
    if (!name.trim() || numericAmount <= 0) return flash('Completa el concepto y el monto.')
    const today = new Date()
    const receivedDate = localDateKey(today)
    const entry = { id: crypto.randomUUID(), name: name.trim(), amount: numericAmount, type: 'income', receivedDate, paymentMethod, note: note.trim(), createdAt: today.toISOString() }
    save({ ...data, incomeEntries: [...(data.incomeEntries || []), entry], profile: { ...data.profile, available: Number(data.profile.available || 0) + numericAmount } }, { type: 'income', title: 'Registraste un ingreso', detail: `${entry.name} · ${money(numericAmount)} · ${paymentMethod}` })
    flash('Ingreso guardado en Movimientos.'); onClose()
  }
  return <section className="page add-page"><div className="page-heading"><div><span className="eyebrow">Nuevo movimiento</span><h1>Nuevo ingreso</h1><p>Registra una entrada puntual, como dinero que te enviaron o una devolución.</p></div><button className="icon-nav-button" onClick={onClose} aria-label="Volver a Inicio" title="Volver a Inicio"><Icon name="arrowLeft" size={18} /></button></div><div className="add-layout income-add-layout"><div className="panel add-selection"><div className="step-block"><Step n="01" title="¿Qué ingreso recibiste?" /><div className="flow-tip"><b>Ingreso real</b><span>Registra cada entrada por separado, igual que registras cada gasto. El saldo se actualizará automáticamente.</span></div></div></div><form className="panel add-summary income-add-form" onSubmit={addIncome}><Step n="02" title="Completa el ingreso" /><label className="form-label">Concepto<input className="field" value={name} onChange={event => setName(event.target.value)} placeholder="Ej. Dinero que me envió mi mamá" autoFocus /></label><label className="form-label">Monto (S/)<input className="field" value={amount} onChange={event => setAmount(event.target.value)} type="number" min="0.01" step="0.01" inputMode="decimal" placeholder="0.00" /></label><label className="form-label">Medio de recepción<select className="field" value={paymentMethod} onChange={event => setPaymentMethod(event.target.value)}>{paymentMethods.map(method => <option key={method} value={method}>{method}</option>)}</select></label><label className="form-label">Nota opcional<textarea className="field note-field" value={note} onChange={event => setNote(event.target.value)} placeholder="Añade un contexto breve..." /></label><button className="primary-button full-button" type="submit">Guardar ingreso <Icon name="arrow" size={17} /></button></form></div></section>
}
function Step({ n, title }) { return <div className="step-title"><span>{n}</span><h2>{title}</h2></div> }

function MovementsView({ data, monthExpenses, currentMonth, onEditExpense, setView }) {
  const monthIncome = (data.incomeEntries || []).filter(item => String(item.receivedDate || item.createdAt || '').slice(0, 7) === currentMonth)
  const movements = [...monthExpenses.map(item => ({ ...item, kind: 'expense', date: item.createdAt })), ...monthIncome.map(item => ({ ...item, kind: 'income', date: item.createdAt || `${item.receivedDate}T12:00:00`, type: 'Ingreso' }))].sort((a, b) => new Date(b.date) - new Date(a.date))
  const totalExpenses = monthExpenses.reduce((sum, item) => sum + item.amount, 0)
  const totalIncome = monthIncome.reduce((sum, item) => sum + Number(item.amount || 0), 0)
  return <section className="page"><div className="page-heading"><div><span className="eyebrow">Historial</span><h1>Movimientos</h1><p>Consulta tus ingresos y gastos del mes en un solo lugar.</p></div><button className="icon-nav-button" onClick={() => setView('home')} aria-label="Volver a Inicio" title="Volver a Inicio"><Icon name="arrowLeft" size={18} /></button></div><div className="panel table-panel"><div className="table-summary"><span><b>{movements.length}</b> movimientos en {monthName}</span><span><b className="income-amount">+{money(totalIncome)}</b> · <b>{money(totalExpenses)}</b> gastados</span></div><div className="table-wrap"><table><thead><tr><th>Fecha y hora</th><th>Tipo</th><th>Detalle</th><th>Nota</th><th>Monto</th><th /></tr></thead><tbody>{movements.length ? movements.map(item => <tr key={`${item.kind}-${item.id}`}><td>{dateTime(item.date)}</td><td>{item.kind === 'income' ? <span className="income-label">Ingreso</span> : data.categories.find(category => category.id === item.categoryId)?.name || 'Categoría eliminada'}</td><td><b>{item.name || item.type}</b></td><td>{item.note || '—'}</td><td><b className={item.kind === 'income' ? 'income-amount' : ''}>{item.kind === 'income' ? '+' : '−'}{money(item.amount)}</b></td><td>{item.kind === 'expense' ? <button className="table-edit" onClick={() => onEditExpense(item)}>Editar nota</button> : null}</td></tr>) : <tr><td colSpan="6"><div className="table-empty">No hay movimientos en este mes.</div></td></tr>}</tbody></table></div></div></section>
}

function CategoriesView({ data, save, editing, editingId, setEditingId, updateEditing, deleteEditing, newType, setNewType, newCategory, setNewCategory, flash }) {
  const [mode, setMode] = useState('list')
  const openEdit = id => { setEditingId(id); setMode('edit') }
  const createCategory = () => { if (!newCategory.name.trim()) return flash('Escribe un nombre.'); const item = { id: crypto.randomUUID(), name: newCategory.name.trim(), budget: Number(newCategory.budget) || 0, flow: newCategory.flow.trim() || 'Registrar monto y detalle.', types: [] }; save({ ...data, categories: [...data.categories, item] }, { type: 'category', title: 'Creaste una categoría', detail: item.name }); setEditingId(item.id); setNewCategory({ name: '', budget: '', flow: '' }); setMode('edit'); flash('Categoría creada.') }
  const addType = () => { const value = newType.trim(); if (value && editing && !editing.types.includes(value)) { updateEditing({ types: [...editing.types, value] }); setNewType('') } }
  return <section className="page narrow-page"><div className="page-heading"><div><span className="eyebrow">Personalización</span><h1>{mode === 'list' ? 'Categorías y tipos' : mode === 'edit' ? 'Editar categoría' : 'Nueva categoría'}</h1><p>{mode === 'list' ? 'Organiza tus gastos sin mezclar edición y creación.' : 'Realiza un cambio y vuelve a la lista cuando termines.'}</p></div>{mode === 'list' ? <button className="primary-button icon-only" onClick={() => setMode('new')} aria-label="Nueva categoría" title="Nueva categoría"><Icon name="plus" size={19} /></button> : <button className="icon-nav-button" onClick={() => setMode('list')} aria-label="Volver a categorías" title="Volver a categorías"><Icon name="arrowLeft" size={18} /></button>}</div>{mode === 'list' && <article className="panel category-list"><div className="panel-heading"><div><span className="panel-label">Tus categorías</span><h2>{data.categories.length} categorías configuradas</h2></div><span className="soft-badge">Activas</span></div><div className="category-list-items">{data.categories.map(item => <div className="category-row" key={item.id}><span className="category-row-icon">{item.name.charAt(0)}</span><span><b>{item.name}</b><small>{item.types.length} tipos · Tope {money(item.budget)}</small></span><span className="category-row-actions"><button onClick={() => openEdit(item.id)} aria-label={`Editar ${item.name}`} title="Editar"><Icon name="tag" size={14} /></button><button onClick={() => deleteEditing(item)} aria-label={`Eliminar ${item.name}`} title="Eliminar"><Icon name="close" size={14} /></button></span></div>)}</div></article>}{mode === 'edit' && editing && <article className="panel category-editor"><div className="editor-heading"><div><span className="panel-label">Categoría seleccionada</span><h2>{editing.name}</h2></div><button className="danger-button" onClick={() => { deleteEditing(editing); setMode('list') }}>Eliminar</button></div><label className="form-label">Nombre<input className="field" value={editing.name} onChange={event => updateEditing({ name: event.target.value })} /></label><label className="form-label">Tope mensual<input className="field" value={editing.budget} onChange={event => updateEditing({ budget: Number(event.target.value) || 0 })} type="number" min="0" step="0.01" /></label><label className="form-label">Descripción del flujo<input className="field" value={editing.flow} onChange={event => updateEditing({ flow: event.target.value })} /></label><div className="types-heading"><h3>Tipos rápidos</h3><span>{editing.types.length} opciones</span></div><div className="type-pills editor-pills">{editing.types.map(item => <span key={item}>{item}<button onClick={() => updateEditing({ types: editing.types.filter(type => type !== item) })} className="icon-delete" aria-label={`Eliminar ${item}`}><Icon name="close" size={13} /></button></span>)}</div><div className="add-type"><input className="field" value={newType} onChange={event => setNewType(event.target.value)} placeholder="Ej. Salud" /><button className="secondary-button" onClick={addType}>Agregar tipo</button></div></article>}{mode === 'new' && <article className="panel new-category"><div className="panel-heading"><div><span className="panel-label">Personalización</span><h2>Crear categoría</h2></div></div><label className="form-label">Nombre<input className="field" value={newCategory.name} onChange={event => setNewCategory({ ...newCategory, name: event.target.value })} placeholder="Ej. Salud" /></label><label className="form-label">Tope mensual<input className="field" value={newCategory.budget} onChange={event => setNewCategory({ ...newCategory, budget: event.target.value })} type="number" placeholder="200" /></label><label className="form-label">Descripción<input className="field" value={newCategory.flow} onChange={event => setNewCategory({ ...newCategory, flow: event.target.value })} placeholder="Registrar consulta, medicina o análisis." /></label><button className="primary-button" onClick={createCategory}>Crear categoría <Icon name="check" size={16} /></button></article>}</section>
}

function SettingsView({ data, profileDraft, setProfileDraft, save, flash, signOut }) {
  const [section, setSection] = useState('home')
  const checks = passwordChecks(profileDraft.password || '')
  const saveProfile = async () => { const profile = { ...profileDraft, password: profileDraft.password ? '' : profileDraft.password, passwordHash: profileDraft.password ? await hashPassword(profileDraft.password) : profileDraft.passwordHash }; save({ ...data, profile }, { type: 'profile', title: 'Actualizaste tu perfil', detail: 'Tus datos principales fueron modificados.' }); setProfileDraft({ ...profile, password: '' }); flash('Perfil guardado.') }
  const heading = section === 'home' ? 'Perfil y ajustes' : section === 'profile' ? 'Datos personales' : section === 'security' ? 'Seguridad' : section === 'activity' ? 'Historial de actividad' : 'Cerrar sesión'
  const Back = () => <button className="icon-nav-button" onClick={() => setSection('home')} aria-label="Volver a Perfil" title="Volver a Perfil"><Icon name="arrowLeft" size={18} /></button>
  if (section === 'home') return <section className="page narrow-page"><div className="page-heading"><div><span className="eyebrow">Tu cuenta</span><h1>Perfil y ajustes</h1><p>Administra tu información sin mezclarla con tus finanzas.</p></div></div><div className="profile-modules"><button className="panel profile-module" onClick={() => setSection('profile')}><span className="insight-icon"><Icon name="user" size={18} /></span><span><b>Datos personales</b><small>Nombre, edad e ingreso mensual.</small></span><Icon name="arrow" size={15} /></button><button className="panel profile-module" onClick={() => setSection('security')}><span className="insight-icon"><Icon name="lock" size={18} /></span><span><b>Seguridad</b><small>Actualiza tu contraseña local.</small></span><Icon name="arrow" size={15} /></button><button className="panel profile-module" onClick={() => setSection('activity')}><span className="insight-icon"><Icon name="list" size={18} /></span><span><b>Historial de actividad</b><small>{data.activity?.length || 0} acciones registradas.</small></span><Icon name="arrow" size={15} /></button><button className="panel profile-module danger-module" onClick={() => setSection('logout')}><span className="insight-icon"><Icon name="logout" size={18} /></span><span><b>Cerrar sesión</b><small>Terminar esta sesión temporal.</small></span><Icon name="arrow" size={15} /></button></div></section>
  if (section === 'activity') return <section className="page narrow-page"><div className="page-heading"><div><span className="eyebrow">Tu cuenta</span><h1>{heading}</h1><p>Consulta todo lo que ocurrió desde la creación de tu cuenta.</p></div><Back /></div><ActivityTimeline activity={data.activity || []} /></section>
  if (section === 'logout') return <section className="page narrow-page"><div className="page-heading"><div><span className="eyebrow">Tu cuenta</span><h1>{heading}</h1><p>Tu información permanece en db.json local.</p></div><Back /></div><div className="panel logout-panel"><span className="insight-icon"><Icon name="logout" size={20} /></span><h2>¿Quieres cerrar tu sesión?</h2><p>Podrás volver a entrar mientras la cuenta está disponible en el almacenamiento local.</p><button className="primary-button" onClick={signOut}>Cerrar sesión <Icon name="logout" size={16} /></button></div></section>
  if (section === 'profile') return <section className="page narrow-page"><div className="page-heading"><div><span className="eyebrow">Tu cuenta</span><h1>Datos personales</h1><p>Actualiza únicamente tus datos de identificación.</p></div><Back /></div><div className="panel settings-panel"><div className="profile-intro"><span className="large-avatar">{(data.profile.name || 'A').charAt(0).toUpperCase()}</span><div><span className="panel-label">Perfil personal</span><h2>{data.profile.name || 'Tu nombre'}</h2><p>{data.profile.email || 'Cuenta temporal'}</p></div></div><hr /><h2>Datos principales</h2><label className="form-label">Nombre<input className="field" value={profileDraft.name} onChange={event => setProfileDraft({ ...profileDraft, name: event.target.value })} /></label><button className="primary-button" onClick={saveProfile}>Guardar cambios <Icon name="arrow" size={16} /></button></div></section>
  return <section className="page narrow-page"><div className="page-heading"><div><span className="eyebrow">Tu cuenta</span><h1>{heading}</h1><p>{section === 'profile' ? 'Actualiza tus datos principales.' : 'Mant?n protegida tu cuenta local.'}</p></div><Back /></div><div className="panel settings-panel">{section === 'profile' ? <><div className="profile-intro"><span className="large-avatar">{(data.profile.name || 'A').charAt(0).toUpperCase()}</span><div><span className="panel-label">Perfil personal</span><h2>{data.profile.name || 'Tu nombre'}</h2><p>{data.profile.email || 'Cuenta temporal'}</p></div></div><hr /><h2>Datos principales</h2><label className="form-label">Nombre<input className="field" value={profileDraft.name} onChange={event => setProfileDraft({ ...profileDraft, name: event.target.value })} /></label><label className="form-label">Ingreso mensual neto<input className="field" value={profileDraft.income} onChange={event => setProfileDraft({ ...profileDraft, income: event.target.value })} type="number" min="0" step="0.01" /></label></> : <><h2>Contrase?a local</h2><p className="settings-help">La contrase?a debe tener entre 8 y 16 caracteres, con may?scula, min?scula y n?mero.</p><label className="form-label">Nueva contrase?a<input className="field" value={profileDraft.password} onChange={event => setProfileDraft({ ...profileDraft, password: event.target.value })} type="password" minLength="8" maxLength="16" placeholder="Nueva contrase?a" /></label>{profileDraft.password && <div className="password-requirements settings-password-requirements"><PasswordRule valid={checks.length} text="8?16 caracteres" /><PasswordRule valid={checks.uppercase} text="Una may?scula" /><PasswordRule valid={checks.lowercase} text="Una min?scula" /><PasswordRule valid={checks.number} text="Un n?mero" /></div>}</>}<button className="primary-button" onClick={saveProfile}>Guardar cambios <Icon name="arrow" size={16} /></button></div></section>
}

function ActivityTimeline({ activity }) {
  return <div className="profile-activity"><div className="section-heading activity-heading"><div><span className="panel-label">Desde el primer día</span><h2>Historial de actividad</h2></div><span className="activity-count">{activity.length} acciones</span></div><div className="panel timeline-panel">{activity.length ? [...activity].reverse().map(item => <ActivityItem key={item.id} item={item} />) : <div className="table-empty">Aún no hay actividad registrada.</div>}</div></div>
}


export { BudgetApp }
